import pandas as pd


def solve(data):
    ban = pd.read_csv('coffee-sales-cc0.csv')
    thang = pd.to_datetime(ban['datetime']).dt.strftime('%Y-%m')
    cua_thang = ban[thang == data]
    return {'thang': data,
            'so_don': int(len(cua_thang)),
            'tong_tien': round(float(cua_thang['money'].sum()), 2),
            'don_vi': 'không xác định'}
